-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Schadsoftware ist eine Gefährdung im IT-Grundschutz. b) Gefährdungen betreffen nur die Vertraulichkeit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schadsoftware ja, alle Schutzziele"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Phishing ist eine Gefährdung im IT-Grundschutz. b) Naturkatastrophen sind keine Gefährdung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Phishing ja, Naturkatastrophen auch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Technische Ausfälle sind Gefährdungen im IT-Grundschutz. b) Gefährdungen sind immer menschenverursacht.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ausfälle ja, nicht nur menschlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Unbefugter Zugriff ist eine Gefährdung im IT-Grundschutz. b) Gefährdungen können vollständig beseitigt werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zugriff ja, nicht eliminierbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Bedienfehler sind Gefährdungen im IT-Grundschutz. b) Stromausfall betrifft nur die Integrität.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Fehler ja, Verfügbarkeit betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

